INSERT INTO `profil_desa` (`id`, `nama_desa`, `foto_desa`, `deskripsi_desa`, `alamat_desa`, `admin_id`, `province_id`, `regency_id`, `district_id`, `village_id`, `created_at`, `updated_at`) VALUES
(1, 'Desa Kare', 'pexels1.jpg', 'Desa Kare Kecamatan Kare Kabupaten Madiun Terletak paling tenggara Kabupaten Madiun. Merupakan Daerah berbatasan dengan Kabupaten Lain yaitu Ponorogo,Trenggalek, Tulungagung, Nganjuk dan Kediri. Merupakan Daerah Pegunungan Wilis yang terdiri dari berbagai bukit dan gunung. Banyak Potensi Wisata yang bersifat alam dan buatan. Untuk itu perlu kebersamaan dalam pengelolaan alam yang ada di Kare melalui berbagai bidang dan inovasi yang terus menerus untuk melestarikan wisata alam tersebut guna kesejahteraan masyarakat Desa Kare.', 'Jl. Raya Kandangan, Gondosuli, Kare, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 6, '35', '3519', '3519060', '3519060003', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(2, 'Desa Bodag', 'pexels2.jpg', 'Desa Bodag Kecamatan Kare Kabupaten Madiun merupakan desa di lereng gunung wilis, wilayahnya berbatasan dengan hutan. Penduduknya bermata pencaharian bertani berkebun dan beternak Tingkat pendidikan yg masih rendah serta mkjp yg renda serta wilayah yg berada di pinggiran membuat dusun butuh desa bodag masuk sebagai kampung KB.', '7J9W+QQ4, Area Kebun/Hutan, Bodag, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 7, '35', '3519', '3519060', '3519060001', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(3, 'Desa Curug Madu', 'pexels3.jpg', 'Desa Wisata Curug Madu terletak di Kabupaten Pekalongan, Jawa Tengah, Indonesia. Desa ini terkenal karena keindahan alamnya yang masih asri dan alami. Di desa ini, terdapat sebuah air terjun yang indah yang bernama Curug Madu. Air terjun ini memiliki ketinggian sekitar 35 meter dan airnya jernih dan segar. Selain air terjun, di desa ini juga terdapat banyak objek wisata lainnya seperti perkebunan teh, kebun stroberi, dan juga banyak warung makan yang menjual makanan khas daerah Pekalongan. Selain itu, Desa Wisata Curug Madu juga dikenal sebagai pusat kerajinan bambu di Pekalongan. Para pengunjung bisa menyaksikan dan membeli berbagai macam produk kerajinan bambu yang dibuat oleh masyarakat setempat. Desa ini menjadi destinasi wisata yang populer di Pekalongan dan sering dikunjungi oleh wisatawan baik dari dalam maupun luar negeri.', 'Lemahbang Lor, Lemah Abang, Kec. Doro, Kabupaten Pekalongan, Jawa Tengah 17438', 8, '32', '3326', '3326060', '3326060003', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(4, 'Desa Kepel', 'pexels1.jpg', 'Desa Wisata Kepel adalah sebuah destinasi wisata yang terletak di Kabupaten Magelang, Jawa Tengah, Indonesia. Desa ini terkenal karena keindahan alamnya yang menawarkan pemandangan yang memukau serta suasana yang tenang dan nyaman.', 'Kepel, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 9, '35', '3519', '3519060', '3519060004', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(5, 'Desa Brumbun', 'pexels1.jpg', 'Desa wisata Brumbun terletak di lereng gunung wilis,tepatnya di kab.Madiun,Jawa timur,dekat dengan kota Madiun,hanya 20 menit saja,kegiatan tubing/kelen adalah kegiatan awal,kemudian sekarang berkembang untuk kegiatan wisata edukasi,kegiatan dikelola oleh Pokdarwis Taruna Utama Brumbun.berdiri sejak tahun 2016.', 'Kepel, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 10, '35', '3519', '3519050', '3519050001', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(6, 'Desa Kayupuring', 'pexels1.jpg', 'Desa Wisata Kayupuring adalah sebuah destinasi wisata yang terletak di Kabupaten Madiun, Jawa Timur, Indonesia. Desa ini dikenal karena keindahan alamnya yang memukau serta kearifan lokal yang kental. Desa Wisata Kayupuring menawarkan suasana yang tenang dan harmoni dengan alam, menjadikannya tempat yang ideal untuk berlibur dan bersantai.', 'Kepel, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 11, '33', '3326', '3326040', '3326040009', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(7, 'Desa Lolong', 'pexels1.jpg', 'Desa Wisata Kayupuring adalah sebuah destinasi wisata yang terletak di Kabupaten Madiun, Jawa Timur, Indonesia. Desa ini dikenal karena keindahan alamnya yang memukau serta kearifan lokal yang kental. Desa Wisata Kayupuring menawarkan suasana yang tenang dan harmoni dengan alam, menjadikannya tempat yang ideal untuk berlibur dan bersantai.', 'Kepel, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 12, '33', '3326', '3326070', '3326070004', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(8, 'Desa Pakumbulan', 'pexels1.jpg', 'Desa Wisata Kayupuring adalah sebuah destinasi wisata yang terletak di Kabupaten Madiun, Jawa Timur, Indonesia. Desa ini dikenal karena keindahan alamnya yang memukau serta kearifan lokal yang kental. Desa Wisata Kayupuring menawarkan suasana yang tenang dan harmoni dengan alam, menjadikannya tempat yang ideal untuk berlibur dan bersantai.', 'Kepel, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 13, '33', '3326', '3326140', '3326140005', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(9, 'Desa Wates', 'pexels1.jpg', 'Desa Wisata Kayupuring adalah sebuah destinasi wisata yang terletak di Kabupaten Madiun, Jawa Timur, Indonesia. Desa ini dikenal karena keindahan alamnya yang memukau serta kearifan lokal yang kental. Desa Wisata Kayupuring menawarkan suasana yang tenang dan harmoni dengan alam, menjadikannya tempat yang ideal untuk berlibur dan bersantai.', 'Kepel, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 14, '33', '3322', '3322010', '3322010010', '2025-04-24 02:45:39', '2025-04-24 02:45:39'),
(10, 'Desa Bejales', 'pexels1.jpg', 'Desa Wisata Kayupuring adalah sebuah destinasi wisata yang terletak di Kabupaten Madiun, Jawa Timur, Indonesia. Desa ini dikenal karena keindahan alamnya yang memukau serta kearifan lokal yang kental. Desa Wisata Kayupuring menawarkan suasana yang tenang dan harmoni dengan alam, menjadikannya tempat yang ideal untuk berlibur dan bersantai.', 'Kepel, Kec. Kare, Kabupaten Madiun, Jawa Timur 63182', 15, '33', '3322', '3322100', '3322100003', '2025-04-24 02:45:39', '2025-04-24 02:45:39');
