(3064, 76, 5695, 'candi cetho merupakan candi di daerah karanganyarjika kita dari solo,membutuh kan waktu tempuh sekitar 1jam dengan menggunakan sepeda motor.jalanan menuju candi cetho kanan kiri jalan banyak kebun teh.dan berliku liku juga jalan menuju kesana nya.', '2023-06-21 00:00:00', ' Teman', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29');
INSERT INTO `review` (`id`, `destinasi_id`, `reviewer_id`, `review_text`, `tanggal`, `status`, `rating`, `jempol`, `created_at`, `updated_at`) VALUES
(3065, 77, 5695, 'candi cetho merupakan candi di daerah karanganyarjika kita dari solo,membutuh kan waktu tempuh sekitar 1jam dengan menggunakan sepeda motor.jalanan menuju candi cetho kanan kiri jalan banyak kebun teh.dan berliku liku juga jalan menuju kesana nya.', '2022-04-12 00:00:00', ' Teman', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(3066, 76, 1999, 'Menuju tempat ini cukup jauh, arah menuju tawangmangu dan cukup mendaki melewati kebun teh tetapi pemandangan cukup bagus dengan udara yang sejuk.Ini ada Candi Hindu, kita bisa melihat candi ini dengan pemandangan diatas bukit. ', '2022-07-22 00:00:00', ' Teman', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(3067, 77, 1999, 'Menuju tempat ini cukup jauh, arah menuju tawangmangu dan cukup mendaki melewati kebun teh tetapi pemandangan cukup bagus dengan udara yang sejuk.Ini ada Candi Hindu, kita bisa melihat candi ini dengan pemandangan diatas bukit. ', '2023-05-01 00:00:00', ' Teman', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(3068, 76, 4160, 'Candi cetho adalah salah satu candi tua di Indonesia. Candi Cetho berada di kemuning dataran tinggi. Jalan menuju candi ini sangat menanjak jadi kalau mau menggunakan kendaraan bermotor disesuaikan dengan medannya ya. Tapi seru kok!!', '2023-04-30 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(3069, 77, 4160, 'Candi cetho adalah salah satu candi tua di Indonesia. Candi Cetho berada di kemuning dataran tinggi. Jalan menuju candi ini sangat menanjak jadi kalau mau menggunakan kendaraan bermotor disesuaikan dengan medannya ya. Tapi seru kok!!', '2023-03-01 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(3070, 76, 5734, 'Ada banyak candi di Indonesia yang dibangun di atas bukit, salah satunya Candi Cetho yang didirikan di lereng Gunung Lawu di Dusun Ceto, Desa Gumeng, Kecamatan Jenawi, Kabupaten Karanganyar. Candi Hindu ini dibangun di lahan bertingkat hingga 14 tingkat sehingga perlu fisik prima untuk sampai ke bagian utama candi di tingkat tertinggi. Prasasti candi yang berbetuk phalus besar kini disimpan di Museum Nasional Jakarta.Candi Cetho diperkirakan dibangun pada masa yang sama dengan Candi Sukuh pada masa Majapahit akhir. Di sini juga ada tatahan batu di permukaan tanah berbetuk kura-kura raksasa, simbol dari penciptaan alam semesta.   ', '2020-11-29 00:00:00', NULL, 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(3071, 77, 5734, 'Ada banyak candi di Indonesia yang dibangun di atas bukit, salah satunya Candi Cetho yang didirikan di lereng Gunung Lawu di Dusun Ceto, Desa Gumeng, Kecamatan Jenawi, Kabupaten Karanganyar. Candi Hindu ini dibangun di lahan bertingkat hingga 14 tingkat sehingga perlu fisik prima untuk sampai ke bagian utama candi di tingkat tertinggi. Prasasti candi yang berbetuk phalus besar kini disimpan di Museum Nasional Jakarta.Candi Cetho diperkirakan dibangun pada masa yang sama dengan Candi Sukuh pada masa Majapahit akhir. Di sini juga ada tatahan batu di permukaan tanah berbetuk kura-kura raksasa, simbol dari penciptaan alam semesta.   ', '2024-08-24 00:00:00', NULL, 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(3072, 76, 1153, 'Candi Cetho.., sebuah candi tertinggi di lereng gunung lawu. Selama perjalanan menuju candi kita akan disuguhi pemandangan alam yg bikin kita berdecak kagum, sejauh mata memandang kita akan disuguhkan jurang2, hamparan perbukitan teh..,udara yg segar jg tentunya. Pada saat saya kesini kebetulan pas sedang kabut. Terkesan indah namun mistis..', '2024-09-05 00:00:00', ' Sendiri', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(3073, 77, 1153, 'Candi Cetho.., sebuah candi tertinggi di lereng gunung lawu. Selama perjalanan menuju candi kita akan disuguhi pemandangan alam yg bikin kita berdecak kagum, sejauh mata memandang kita akan disuguhkan jurang2, hamparan perbukitan teh..,udara yg segar jg tentunya. Pada saat saya kesini kebetulan pas sedang kabut. Terkesan indah namun mistis..', '2022-06-24 00:00:00', ' Sendiri', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
