INSERT INTO `review` (`id`, `destinasi_id`, `reviewer_id`, `review_text`, `tanggal`, `status`, `rating`, `jempol`, `created_at`, `updated_at`) VALUES
(8275, 320, 4761, 'Tanda jalan menuju lokasi cukup jelas. Display dan informasi yang disajikan di dalam museum cukup lengkap dan mudah dimengerti. Setelah berpuluh tahun belajar tentang manusia pra sejarah dan sulit untuk memahami, dengan berkunjung ke museum ini saya jadi mengerti.', '2021-01-23 00:00:00', ' Pasangan', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(8276, 319, 535, 'Perjalanan sekitar 1 jam dari Solo. Lokasi mudah ditemukan, ada banyak petunjuk menuju museum. Museum manusia purba, lengkap, mendidik. Tempat kebanyakan didalam ruangan ber ac, dilengkapi dengan diorama yang apik', '2020-05-09 00:00:00', ' Keluarga', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(8277, 320, 535, 'Perjalanan sekitar 1 jam dari Solo. Lokasi mudah ditemukan, ada banyak petunjuk menuju museum. Museum manusia purba, lengkap, mendidik. Tempat kebanyakan didalam ruangan ber ac, dilengkapi dengan diorama yang apik', '2020-06-24 00:00:00', ' Keluarga', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(8278, 319, 6790, 'Rambu arah menuju museum terlihat jelas dari tugu \'Welcome to Sangiran Archaeological Site\' bergambar gajah/manusia purba, dari jalan raya Solo-Purwodadi masuk +/- 2,5 km ke timur lewat gerbang \'Situs Sangiran\' yang unik Dengan membayar tiket masuk Rp 5 ribu plus karcis parkir roda-4 Rp 5 ribu kita mulai masuk gerbang yaang dihiasi dua gading besar dan patung manusia purba Sangiran (The Homeland of Javaman) menuju ke koridor museum yang luas & terpelihara. Ada dua pintu masuk: Ruang Pamer-1 (Kekayaan Sangiran) & Ruang Pamer-2 (Langkah Kemanusiaan),masing-masing berisi koleksi aneka ragam yang berbeda: masalah alam semesta, pulau Jawa, kehidupan flora-fauna zaman dulu, dan fokus utama tentang manusia purba/\'homo erectus\' (ada tiga jenis: arkais,tipik/ klasik & progresif) yang mengalami evolusi sampai menjadi manusia modern/ \'homo sapiens\' melalui proses penggalian fosil di situs & penelitian oleh ilmuwan seperti: Charles Darwin, Wallacea, Dubois, van Koenigswald, Mendel dst serta ilmuwan dari Indonesia seperti: Prof. Soejono,Prof.Sartono & Prof.Teuku Jacob terus dilanjutkan generasi penerusnya. Temuan terbaru (2015) di Sangiran:gading gajah,tulang belakang gajah & rahang bawah buaya. Semuanya disajikan dengan bagus dalam ruangan ber-AC,tata cahaya & diorama yang menakjubkan; butuh waktu lama untuk menikmati detail isi museum yang lengkap,penuh edukatif, selasar/koridornya panjang & berliku dari lantai-1 s/d 2,pengunjung di kawal oleh security yang \'care\'.Sebetulnya selain Museum Prasejarah Sangiran (masuk area situs Krikilan) sebagai \'World Heritage\' UNESCO masih ada museum-museum lainnya seperti: Klaster Ngebung (jarak 3 km dari Krikilan),Klaster Bukuran (4 km dari Krikilan atau 5,5 km dari jalan raya),museum pendukung Manyarejo (4,5 km dari Krikilan/ 6,3 km dari jalan raya) dan Klaster Dayu (11 km dari Krikilan). Ada beberapa rumah penduduk yang menjual souvenir di jalan menuju museum. Saat kami ke sana ada project pembangunan jembatan yang berbentuk unik disebelah museum  Dari \'Bigbang\' hingga Sangiran tercipta, silahkan nikmati sensasinya...', '2023-01-14 00:00:00', ' Pasangan', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
