INSERT INTO `review` (`id`, `destinasi_id`, `reviewer_id`, `review_text`, `tanggal`, `status`, `rating`, `jempol`, `created_at`, `updated_at`) VALUES
(10813, 245, 1791, 'klenteng tertua dan lokasi di daerah kota lama semarang. sampingnya ada makanan khas semarang yaitu lumpia.kalau mau berdoa atau bertanya hal di masa depan juga bisa.', '2022-08-29 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10814, 244, 4064, 'Letaknya di dalam gang kecil. Kuilnya pun tidak besar, hanya ada satu aula besar di dalam dengan beberapa tempat sembahyang.Bangunannya pun kurang terawat dan terjaga. Kurang bisa menarik wisatawan.', '2022-07-12 00:00:00', ' Teman', 2, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10815, 245, 4064, 'Letaknya di dalam gang kecil. Kuilnya pun tidak besar, hanya ada satu aula besar di dalam dengan beberapa tempat sembahyang.Bangunannya pun kurang terawat dan terjaga. Kurang bisa menarik wisatawan.', '2022-03-24 00:00:00', ' Teman', 2, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10816, 244, 240, 'Klenteng Tay Kak Sie merupakan salah satu bangunan klenteng kuno di kota semarang yang masih terawat dengan baik. Di dalam klenteng ini ada banyak sekali dewa sehingga biasa disebut sebagai \"Klenteng Besar\". Lokasinya memang dari jalan besar tak terlihat, tetapi sangat gampang di cari karena persis di akhir jalan pekojan belok kanan menyusuri sungai ketemu deh. Di areal klenteng ini sangat luas, apalagi kalau ada upacara ultah dewa Sampo Tay Jien, akan ada perarakan meriah dari klenteng ini ke klenteng sam poo kong diiringi tarian liong dan barongsay sangat meriah sekali. Klenteng ini terbuka untuk wisatawan dan tidak di pungut beaya, tetapi alangkah baiknya kalau bisa memberi derma untuk perawatan bangunan klenteng ini.', '2021-09-01 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10817, 245, 240, 'Klenteng Tay Kak Sie merupakan salah satu bangunan klenteng kuno di kota semarang yang masih terawat dengan baik. Di dalam klenteng ini ada banyak sekali dewa sehingga biasa disebut sebagai \"Klenteng Besar\". Lokasinya memang dari jalan besar tak terlihat, tetapi sangat gampang di cari karena persis di akhir jalan pekojan belok kanan menyusuri sungai ketemu deh. Di areal klenteng ini sangat luas, apalagi kalau ada upacara ultah dewa Sampo Tay Jien, akan ada perarakan meriah dari klenteng ini ke klenteng sam poo kong diiringi tarian liong dan barongsay sangat meriah sekali. Klenteng ini terbuka untuk wisatawan dan tidak di pungut beaya, tetapi alangkah baiknya kalau bisa memberi derma untuk perawatan bangunan klenteng ini.', '2024-08-31 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10818, 244, 583, 'Bukan kelenteng Sam Po Kong ternyata yang sebagai kelenteng paling berpengaruh oleh warga penganut aliran Kong Hu Cu atau Konfusianism, tetapi Thay Kak Sie, sebuah kelenteng yang dibangun lebih dari 400 tahun lamanya, kelenteng yang menjadi pusat dari tiga aliran utama di China daratan yaitu Buddha, Tao dan Konfusianism, kemungkinan hanya ada satu kelenteng di Indonesia dimana sebuah kelenteng menjadi rumah dari 3 aliran utama. ', '2020-09-05 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10819, 245, 583, 'Bukan kelenteng Sam Po Kong ternyata yang sebagai kelenteng paling berpengaruh oleh warga penganut aliran Kong Hu Cu atau Konfusianism, tetapi Thay Kak Sie, sebuah kelenteng yang dibangun lebih dari 400 tahun lamanya, kelenteng yang menjadi pusat dari tiga aliran utama di China daratan yaitu Buddha, Tao dan Konfusianism, kemungkinan hanya ada satu kelenteng di Indonesia dimana sebuah kelenteng menjadi rumah dari 3 aliran utama. ', '2021-06-04 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10820, 244, 1406, 'Kelenteng Tay Kak Sie Semarang sebagai tempat wisata spiritual. Sebagai kelenteng yang tua namun masih berdiri kokoh, sangat terkenal sampai manca negara. Ada hal yang sangat menarik untuk para wisatawan bahwa di kelenteng ini ada patung orang tua yang sedang mengail di kolam teratai, uniknya tali pancing ini tidak ada mata kailnya. Patung ini menggambarkan orang tua yang sabar dengan penuh kasih sayang. Ornamen naga dan harimau menghiasi beberapa panel. Kelenteng ini sekarang juga di lengkapi dengan patung laksamana Ceng Ho. Paling depan tumbuh besar dan kokoh pohon Bodhi yang melambangkan perjuangan,', '2021-12-26 00:00:00', ' Pasangan', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10821, 245, 1406, 'Kelenteng Tay Kak Sie Semarang sebagai tempat wisata spiritual. Sebagai kelenteng yang tua namun masih berdiri kokoh, sangat terkenal sampai manca negara. Ada hal yang sangat menarik untuk para wisatawan bahwa di kelenteng ini ada patung orang tua yang sedang mengail di kolam teratai, uniknya tali pancing ini tidak ada mata kailnya. Patung ini menggambarkan orang tua yang sabar dengan penuh kasih sayang. Ornamen naga dan harimau menghiasi beberapa panel. Kelenteng ini sekarang juga di lengkapi dengan patung laksamana Ceng Ho. Paling depan tumbuh besar dan kokoh pohon Bodhi yang melambangkan perjuangan,', '2024-01-22 00:00:00', ' Pasangan', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10822, 244, 2674, 'Salah satu klenteng terbesar di sekitar pecinan Semarang. Sangat menyenangkan saat berkunjung pada saat tahun baru china dengan atraksi barong sai dan pertunjukan lain. Lokasinya cukup strategis, dan masih dapat dijangkau dengan angkutan umum dari pusat kota', '2020-05-12 00:00:00', ' Teman', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10823, 245, 2674, 'Salah satu klenteng terbesar di sekitar pecinan Semarang. Sangat menyenangkan saat berkunjung pada saat tahun baru china dengan atraksi barong sai dan pertunjukan lain. Lokasinya cukup strategis, dan masih dapat dijangkau dengan angkutan umum dari pusat kota', '2021-03-11 00:00:00', ' Teman', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(10824, 244, 1548, 'Klenteng Tay Kak Sie ini berada di daerah Pecinan, tepatnya di Gang Lombok. Sayangnya saat saya kesana, hari sudah sore. Dan sepertinya baru saja dilaksanakan acara disana. Karena adanya tenda-tenda yang dipasang disana. kalau kita datang ke gang Lombok. Kita akan langsung disuguhi dengan 2 objek yang berdekatan. Yaitu klenteng Tay Kak Sie ini, dan juga Lumpia Gang Lombok yang berada tepat disebelahnya', '2021-10-21 00:00:00', ' Sendiri', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
