(11659, 338, 1906, 'Pulau batu topeng destinasi yang jadi pilihan ke dua setelah karimun jawa,bagus sambil nikmatin degan segerr', '2024-07-19 00:00:00', ' Bisnis', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11660, 338, 5682, 'Salah satu destinasi wisata pulau di Karimun Jawa yang layak anda coba.Keindahan Pulau nya tidak kalah dengan pulau2 di sekitarnya.', '2023-01-02 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11661, 338, 4828, 'sekarang agak ramai, disini dekat dengan sunset beach juga dan arahnya sama dengan tanjung gelam....', '2025-02-07 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11662, 338, 5295, 'Sebelum menjelajah semua kepulauan karimun jawa kami menyempatkan diri untuk latihan snorkling di pantai batu topeng sekaligus menikmati es kelapa muda. enak tenan!', '2021-11-25 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11663, 338, 654, 'Pantai batu topeng ini disebut-sebut sebagai belitung nya kepulauan karimun jawa, terdapat bebatuan besar yang berada di bibir pantai dengan air laut yang sangat jernih memberikan kesan seperti di Belitung', '2023-11-12 00:00:00', ' Teman', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11664, 338, 6472, 'Pantai ini bersebelahan dengan pantai tanjung gelam dengan view yang sama bagusnya dan fasilitas yang mirip tapi lebih kecil pantainya. Harus dikunjungi. Istimewa banget. Cocok utk latihan snorkling dengan pengawasan guide profesional tentunya. Istimewa.', '2021-03-06 00:00:00', ' Pasangan', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11665, 338, 363, 'Snorkling di sini benar-benar keren dan mantabIkan-ikannya aggresif, datang menghampiri dan juga banyak sekali berombonganapalagi kalau di kasih roti...view underwaternya super...', '2024-07-10 00:00:00', ' Pasangan', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29');
INSERT INTO `review` (`id`, `destinasi_id`, `reviewer_id`, `review_text`, `tanggal`, `status`, `rating`, `jempol`, `created_at`, `updated_at`) VALUES
(11666, 338, 1052, 'Pantai tenang yang bagus, bersih. Bukan pantai terbaik untuk berenang karena ada karang dan bebatuan, tetapi untuk bersantai dan berjemur, ini adalah pantai yang bagus untuk menunggu matahari terbenam. Warung yang bagus, lapangan voli, dan makanan jika Anda merasa laparSangat indah', '2020-05-28 00:00:00', ' Sendiri', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11667, 338, 6849, 'Ini adalah salah satu pantai terbaik di pulau ini, sangat tenang, dengan warung kecil yang bagus untuk makan dan minum jus. Bintik untuk matahari terbenam dan dingin', '2024-06-01 00:00:00', ' Sendiri', 5, 1, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11668, 338, 4107, 'memasuki Sunset Beach, berjalan ke kiri untuk menemukan pantai terbaik. ada sebuah kios bernama Samudra Seafood yang membuat barbeque seafood terbaik. Itu adalah tempat favorit kami, kami pergi ke sana setiap hari.', '2024-10-12 00:00:00', ' Pasangan', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11669, 338, 1906, 'Pulau batu topeng destinasi yang jadi pilihan ke dua setelah karimun jawa,bagus sambil nikmatin degan segerr', '2024-05-25 00:00:00', ' Bisnis', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11670, 338, 5682, 'Salah satu destinasi wisata pulau di Karimun Jawa yang layak anda coba.Keindahan Pulau nya tidak kalah dengan pulau2 di sekitarnya.', '2021-08-15 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11671, 338, 4828, 'sekarang agak ramai, disini dekat dengan sunset beach juga dan arahnya sama dengan tanjung gelam....', '2022-05-28 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(11672, 338, 5295, 'Sebelum menjelajah semua kepulauan karimun jawa kami menyempatkan diri untuk latihan snorkling di pantai batu topeng sekaligus menikmati es kelapa muda. enak tenan!', '2022-05-12 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
