INSERT INTO `review` (`id`, `destinasi_id`, `reviewer_id`, `review_text`, `tanggal`, `status`, `rating`, `jempol`, `created_at`, `updated_at`) VALUES
(12986, 44, 5943, 'ini adalah peninggalan sejarah dan budaya. Benteng peninggalan Belanda ini terdapat hotel (penginapan) di kompleksnya. Lokasinya yang dekat dengan stasiun Gombong.Perlu dirawat dan diberikan keterangan yang memadai bagi wisatawan yang berkunjung.', '2024-01-01 00:00:00', ' Teman', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(12987, 45, 5943, 'ini adalah peninggalan sejarah dan budaya. Benteng peninggalan Belanda ini terdapat hotel (penginapan) di kompleksnya. Lokasinya yang dekat dengan stasiun Gombong.Perlu dirawat dan diberikan keterangan yang memadai bagi wisatawan yang berkunjung.', '2024-09-21 00:00:00', ' Teman', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(12988, 44, 6721, 'Benteng pertahanan Hindia Belanda yang dibangun pada abad ke 18. Benteng ini terletak di kota Gombong, sekitar 20 km sebelah barat dari Ibukota kabupaten Kebumen, Jawa Tengah, 7 km Barat Kota Karanganyar, atau 100 km dari Yogyakarta.Nama benteng ini diambil dari Van Der Wijck, yang kemungkinan nama komandan pada saat itu. Nama benteng ini terpampang pada pintu sebelah kanan.Berlokasi di Jalan Sapta Marga No. 100, Sidayu, Gombong, Kabupaten Kebumen, Jawa Tengah 54416', '2022-12-23 00:00:00', ' Keluarga', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(12989, 45, 6721, 'Benteng pertahanan Hindia Belanda yang dibangun pada abad ke 18. Benteng ini terletak di kota Gombong, sekitar 20 km sebelah barat dari Ibukota kabupaten Kebumen, Jawa Tengah, 7 km Barat Kota Karanganyar, atau 100 km dari Yogyakarta.Nama benteng ini diambil dari Van Der Wijck, yang kemungkinan nama komandan pada saat itu. Nama benteng ini terpampang pada pintu sebelah kanan.Berlokasi di Jalan Sapta Marga No. 100, Sidayu, Gombong, Kabupaten Kebumen, Jawa Tengah 54416', '2022-12-25 00:00:00', ' Keluarga', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(12990, 44, 3669, 'Benteng ini lokasi tepatnya masuk di dalam Kecamatan Gombong, sepertinya benteng ini adalah salah satu peninggalan penjajah Belanda, namun kami kurang paham siapa yang membangun dan diambil dari nama siapa, info yang ada hanya menyatakan benteng ini dibangun tahun 1881 dan direnovasi sekitar tahun 1998. Bentengnya tidak terlalu luas dan saat ini dijadikan tempat wisata, cukup banyak spot untuk berfoto dan di dalam ruangan banyak terdapat foto-foto proses renovasi benteng ini. Di atas benteng kita bisa naik kereta mengitari benteng, sementara itu di depan area benteng terdapat hotel wisata dimana kita bisa menginap dan terdapat sebuah gedung aula yang bisa dipergunakan untuk acara gathering atau pernikahan. Dibutuhkan perhatian bersama dari pemerintah dan masyarakat untuk menjaga dan melestarikan peninggalan sejarah ini.', '2021-11-28 00:00:00', ' Teman', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
