INSERT INTO `review` (`id`, `destinasi_id`, `reviewer_id`, `review_text`, `tanggal`, `status`, `rating`, `jempol`, `created_at`, `updated_at`) VALUES
(22760, 80, 6772, 'Kuil ini cukup rata-rata meskipun, dan tidak sangat besar, itu worth mengambil perjalanan di sini untuk melihat matahari terbenam di seluruh yogyakarta', '2022-09-26 00:00:00', ' Keluarga', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22761, 81, 6772, 'Kuil ini cukup rata-rata meskipun, dan tidak sangat besar, itu worth mengambil perjalanan di sini untuk melihat matahari terbenam di seluruh yogyakarta', '2020-03-30 00:00:00', ' Keluarga', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22762, 80, 3329, 'Untuk tiba di sana adalah sedikit lama dan jalan tidak sempurna secara keseluruhan, tapi itu pasti patut dikunjungi. Itu bisa mendapatkan sibuk pada sore hari dengan pasangan atau pergi-untuk-pasangan menonton matahari terbenam. Kuil yang kompleks yang terletak di teras di atas 17 teras-gunung. Di perjalanan anda dapat melihat batu yang indah menjadi agenda pagelaran budaya beberapa bulan yang lalu. ', '2022-01-13 00:00:00', ' Keluarga', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22763, 81, 3329, 'Untuk tiba di sana adalah sedikit lama dan jalan tidak sempurna secara keseluruhan, tapi itu pasti patut dikunjungi. Itu bisa mendapatkan sibuk pada sore hari dengan pasangan atau pergi-untuk-pasangan menonton matahari terbenam. Kuil yang kompleks yang terletak di teras di atas 17 teras-gunung. Di perjalanan anda dapat melihat batu yang indah menjadi agenda pagelaran budaya beberapa bulan yang lalu. ', '2023-09-12 00:00:00', ' Keluarga', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22764, 80, 5580, 'Untuk mencapai kuil ijo membutuhkan beberapa penguasahaan. Saya melakukan perjalanan dengan sepeda motor untuk mencapai tempat ini. Anda akan menemukan pemandangan indah ketika anda mencapai candi. Sejumlah kuil yang berfungsi ketika aku ada di sana', '2023-08-30 00:00:00', ' Keluarga', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22765, 81, 5580, 'Untuk mencapai kuil ijo membutuhkan beberapa penguasahaan. Saya melakukan perjalanan dengan sepeda motor untuk mencapai tempat ini. Anda akan menemukan pemandangan indah ketika anda mencapai candi. Sejumlah kuil yang berfungsi ketika aku ada di sana', '2023-07-17 00:00:00', ' Keluarga', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22766, 80, 2621, 'Kuil ini perlu perhatian karena pemerintah setempat masih sangat gersang, pohon langka, dan tidak terpelihara dengan baik... harus lebih menarik karena lokasi di atas kota dan udara yang sejuk', '2021-11-17 00:00:00', ' Keluarga', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22767, 81, 2621, 'Kuil ini perlu perhatian karena pemerintah setempat masih sangat gersang, pohon langka, dan tidak terpelihara dengan baik... harus lebih menarik karena lokasi di atas kota dan udara yang sejuk', '2022-11-06 00:00:00', ' Keluarga', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22768, 80, 5926, 'Kami menemukan hotel ini melalui internet dan kuil hindu memutuskan untuk mengunjungi karena ini adalah perjalanan kami keempat ke jogja dan kami telah melihat kuil dan situs wisata utama lainnya. Kami adalah sekelompok 10 dan makan oleh van. Candi ijo (kuil) berjarak sekitar 18 km dari jogja dan berada di puncak bukit yang ijo Gumuk merupakan titik tertinggi di jogja. Pergi di sore hari untuk melihat keindahan sunset yang menakjubkan dan menyaksikan acara. Waspadalah terhadap perjalanan ke atas bukit meskipun, itu mengguncang tulang! Jalan sempit di tengah-tengah desa ini memiliki kualitas tinggi dan kami hampir dilempar keluar dari kursi kami! Masuk ke kuil ini gratis, sumbangan yang diterima. Sebuah tangga pendek di atas dan kami berada di kawasan candi. Itu bukan sebagai ramai sebagai prambanan, mahasiswa dan pasangan muda yang bagus di sekitar. Lingkungan itu tenang dan damai dengan pemandangan persawahan dan daerah sekitarnya. Terdapat sejumlah kuil di sini, sebagian besar kosong kecuali untuk sedikit bangunan kuil yang besar dan yoni lingam (& siwa Shakti). Kuil ini cukup gelap karena tinggi piramid seperti atap berlapis-lapis. Dan tepat di seberang adalah kuil kecil yang menghadap taman perumahan Nandi, (siwa kendaraan, banteng). Matahari terbenam di belakang kuil Nandi, tetapi cahaya matahari tidak jatuh tepat di bawah lingam. Saat matahari terbenam, sinarnya bepergianlah plus lingam dan kegiatan di seluruh kuil beranekawarna. Saat yang indah, mungkin 5 menit berkelanjutan. Kami merasa diberkati dan terpesona oleh tempat yang menakjubkan dari orang-orang yang membangun candi. Pihak berwenang telah ditemukan banyak kuil di daerah sekitar dan jadi ini mungkin akan menjadi lebih terkenal di daerah dan itu penuh sesak. ', '2022-02-20 00:00:00', NULL, 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22769, 81, 5926, 'Kami menemukan hotel ini melalui internet dan kuil hindu memutuskan untuk mengunjungi karena ini adalah perjalanan kami keempat ke jogja dan kami telah melihat kuil dan situs wisata utama lainnya. Kami adalah sekelompok 10 dan makan oleh van. Candi ijo (kuil) berjarak sekitar 18 km dari jogja dan berada di puncak bukit yang ijo Gumuk merupakan titik tertinggi di jogja. Pergi di sore hari untuk melihat keindahan sunset yang menakjubkan dan menyaksikan acara. Waspadalah terhadap perjalanan ke atas bukit meskipun, itu mengguncang tulang! Jalan sempit di tengah-tengah desa ini memiliki kualitas tinggi dan kami hampir dilempar keluar dari kursi kami! Masuk ke kuil ini gratis, sumbangan yang diterima. Sebuah tangga pendek di atas dan kami berada di kawasan candi. Itu bukan sebagai ramai sebagai prambanan, mahasiswa dan pasangan muda yang bagus di sekitar. Lingkungan itu tenang dan damai dengan pemandangan persawahan dan daerah sekitarnya. Terdapat sejumlah kuil di sini, sebagian besar kosong kecuali untuk sedikit bangunan kuil yang besar dan yoni lingam (& siwa Shakti). Kuil ini cukup gelap karena tinggi piramid seperti atap berlapis-lapis. Dan tepat di seberang adalah kuil kecil yang menghadap taman perumahan Nandi, (siwa kendaraan, banteng). Matahari terbenam di belakang kuil Nandi, tetapi cahaya matahari tidak jatuh tepat di bawah lingam. Saat matahari terbenam, sinarnya bepergianlah plus lingam dan kegiatan di seluruh kuil beranekawarna. Saat yang indah, mungkin 5 menit berkelanjutan. Kami merasa diberkati dan terpesona oleh tempat yang menakjubkan dari orang-orang yang membangun candi. Pihak berwenang telah ditemukan banyak kuil di daerah sekitar dan jadi ini mungkin akan menjadi lebih terkenal di daerah dan itu penuh sesak. ', '2024-05-13 00:00:00', NULL, 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22770, 80, 3729, 'Kuil ini berada di bawah renovasi tapi masih terbuka untuk publik.Ijo berarti hijau, tapi tidak tahu namun sangkut pautnya.bagus untuk melihat tapi berhati-hati dari batu bata.', '2022-11-08 00:00:00', ' Pasangan', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22771, 81, 3729, 'Kuil ini berada di bawah renovasi tapi masih terbuka untuk publik.Ijo berarti hijau, tapi tidak tahu namun sangkut pautnya.bagus untuk melihat tapi berhati-hati dari batu bata.', '2021-06-29 00:00:00', ' Pasangan', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22772, 80, 3864, 'Aku tahu aku waktu yang buruk datang di sekitar 11am saat ini super panas dan lembab, tapi hei! Setidaknya tempat ini gratis untuk mengunjungi. Tempat ini adalah cukup jauh dari prambanan/terdekat hidung, dan terletak di atas sebuah bukit besar. Jalan setapak di naik adalah gila dengan banyak lubang dan jalan terjal sehior. Situs itu sendiri terdiri dari satu candi utama dan tiga yang kecil. Di dalam mereka memiliki lucu duduk karena di dalamnya. Itu adalah benar-benar puncak jika kunjungan saya. Sisanya hanya memiliki beberapa relief di dalam dan tidak pernah arcas. Mungkin tempat ini akan tampak jauh lebih baik di lingkungan matahariterbenam. ', '2022-02-25 00:00:00', ' Teman', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22773, 81, 3864, 'Aku tahu aku waktu yang buruk datang di sekitar 11am saat ini super panas dan lembab, tapi hei! Setidaknya tempat ini gratis untuk mengunjungi. Tempat ini adalah cukup jauh dari prambanan/terdekat hidung, dan terletak di atas sebuah bukit besar. Jalan setapak di naik adalah gila dengan banyak lubang dan jalan terjal sehior. Situs itu sendiri terdiri dari satu candi utama dan tiga yang kecil. Di dalam mereka memiliki lucu duduk karena di dalamnya. Itu adalah benar-benar puncak jika kunjungan saya. Sisanya hanya memiliki beberapa relief di dalam dan tidak pernah arcas. Mungkin tempat ini akan tampak jauh lebih baik di lingkungan matahariterbenam. ', '2021-09-20 00:00:00', ' Teman', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22774, 80, 2298, 'Ijo tentang 20 km dari kota yogyakarta. Anda dapat menemukannya di google maps.Anda sebaiknya menggunakan mobil pribadi atau menyewa sepeda motor atau mobil untuk sampai ke sana, karena tidak ada transportasi umum yang pergi ke sana.Hati-hati, perjalanan ke candi ijo ini berbahaya. Kota ini terletak di atas bukit.Hal-hal terbaik tentang candi ijo adalah matahari yang terbenam. Saya sangat merekomendasikan anda untuk pergi ada di musim kemarau (juni-september). Dan anda harus pergi ke sana sekitar 4 pm untuk 5 pm (waktu setempat). Dan anda akan menikmati pemandangan indah matahari terbenam di candi ijo.Dan kabar baik, candi ijo adalah candi tidak gratis. Anda tidak perlu membayar biaya masuk. Hotel ini secara resmi dari pemerintah daerah Sleman. jadi jika anda pemandu wisata atau seseorang di sana meminta anda untuk biaya masuk, hal ini dianggap ilegal. Satu-satunya hal adalah anda harus membayar parkir kendaraan untuk IDR 2,000 - 5,000.Menikmati ini', '2022-05-20 00:00:00', NULL, 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22775, 81, 2298, 'Ijo tentang 20 km dari kota yogyakarta. Anda dapat menemukannya di google maps.Anda sebaiknya menggunakan mobil pribadi atau menyewa sepeda motor atau mobil untuk sampai ke sana, karena tidak ada transportasi umum yang pergi ke sana.Hati-hati, perjalanan ke candi ijo ini berbahaya. Kota ini terletak di atas bukit.Hal-hal terbaik tentang candi ijo adalah matahari yang terbenam. Saya sangat merekomendasikan anda untuk pergi ada di musim kemarau (juni-september). Dan anda harus pergi ke sana sekitar 4 pm untuk 5 pm (waktu setempat). Dan anda akan menikmati pemandangan indah matahari terbenam di candi ijo.Dan kabar baik, candi ijo adalah candi tidak gratis. Anda tidak perlu membayar biaya masuk. Hotel ini secara resmi dari pemerintah daerah Sleman. jadi jika anda pemandu wisata atau seseorang di sana meminta anda untuk biaya masuk, hal ini dianggap ilegal. Satu-satunya hal adalah anda harus membayar parkir kendaraan untuk IDR 2,000 - 5,000.Menikmati ini', '2023-07-17 00:00:00', NULL, 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22776, 349, 1751, 'Pantai indah ini masih belum banyak pengunjung. Bersih dan bagus pemandangannya. Ombak yg cukup besar tidak disarankan untuk berenang.', '2022-11-13 00:00:00', ' Keluarga', 5, 1, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22777, 349, 1959, 'Banyak oleh oleh dan penjual souvenir disini, serta warung warung yang menjajakan kelapa muda untuk penghilang rasa haus..', '2020-01-27 00:00:00', ' Keluarga', 4, 1, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22778, 349, 2304, 'Bukit Pantai Krakal senja hari samgat indah dan cocok tuk melihat sunset. Kita bisa menaiki bukit dengan berjalan kaki atau naik ojeg dgn ongkos 3000 untuk naik dan 3000 untuk turun. Pantainya memiliki karang dan aman tuk main air😅. Ketika berkunjun ke sini, jangan lupa kunjungi Warung Makan Bu Prapti. Makanannya sangat enak. Happy holiday ', '2025-02-10 00:00:00', ' Pasangan', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22779, 349, 4488, 'Bintang 🌟 4Pantai dengan pemandangan indah.Batu2 yg unik dan menarik. Fasilitas yg lengkap dengan parkir luas. Biaya perorang Rp10.000 untuk pantai2 sepanjang gn. Kidul.Restoran seafood yg menyediakan hasil laut yg segar, homestay yg cukup murah .Sangat rekomended untuk keluarga. ', '2024-08-14 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22780, 349, 3808, '1. Lokasi dekat sekali dengan jalan raya2. Bayar karcis masuk 5000, padahal di papan cuma 30003. Parkir luas (suka-suka parkirnya)4. Ada icon pantai krakal yang ada di atas bukit. Bisa jalan kaki ke sana dan melihat pemandangannya dari atas. ', '2024-11-07 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22781, 349, 1310, 'Pantai Krakal adalah pantai yang bedekan dengan pantai IndrayantiPantai Krakal mempunyai tebing yang menilang untuk menikmati pantai,dari tebing tersebut kita bisa juga melihat pantai yang ada di sebelahnya yaitu pantai Indrayanti pantai Krakal bagus juga sih banyak tebing bebatuan yang bagus banget parah daratan yang terpampang di pinggir pantai   kaya lagi dimana gitu rasanya', '2022-06-28 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22782, 349, 4311, 'Berangkat dari jogja jam 7 dan sampai di pantai jam 9.Tiket masuk wisata pantai gunung kidul 10rb/ orang. Untuk ke pantai krakal, cuma bayar parkir 2rb untuk sepeda motor dan 5rb untuk mobil.Pantai krakal ada 2 bagian, disebelah barat pantai lebih sepi.Kalau bawa anak kecil, mending di sebelah timur lebih landai dan aman.Sambil menunggu anak anak bermain, bisabisa sewa tikar, 15rb seharianBisa beli oleh-oleh juga, pisang, buah srikaya (saat musim) , ikan dan udang.', '2022-02-10 00:00:00', NULL, 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22783, 349, 259, 'Pantai ini dapat dinikmati baik dari ketinggian karna memiliki tebing yang cukup bagus untuk spot foto, juga memiliki pasir yang halus. Tapi saya tidak merekomendasikan untuk berenang karna karangnya cukup banyak dan tajam. Hanya bermain pasir di pinggir pantai tidak ada salahnya kan. Para pedangan di pantai ini sangat ramah, untuk masuk ke pantai ini hanya dengan biaya parkr saja tidak ada biaya retribusi lainnya. Sangat cocok untuk liburan keluarga. Sepanjang pantai gunung kidul pantai ini menurut saya termasuk yang lengkap fasilitasnya. Semoga pengunjung lain juga dapat menikmati liburan di pantai ini.', '2020-11-14 00:00:00', ' Pasangan', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(22784, 349, 3677, 'Pantainya bersih. Tapi pantai karang, jadi kurang leluasa untuk bermain air. Ada bagian tebing yang bisa dinikmati.Banyak tersedia toilet dan warung di pinggir pantai. ', '2020-04-26 00:00:00', ' Teman', 3, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
