INSERT INTO `review` (`id`, `destinasi_id`, `reviewer_id`, `review_text`, `tanggal`, `status`, `rating`, `jempol`, `created_at`, `updated_at`) VALUES
(27389, 53, 3977, 'Pagi hari udara sejuk, Indah, nikmat gowes bersama 23 asatidz Pondok Pesantren Darunnajah, Klangon ke Prambanan sejauh 23 km', '2020-11-29 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27390, 53, 2387, 'Baru kali ini berada dekat dengan puncak Merapi setelah dulu pernah tinggal di Yogya, sayang kabut sudh turun dan tebal. Meski tidak bisa melihat puncak Merapi ( kata guide ini memandang Merapi terdekat tanpa perlu mendaki gunung), kami nikmati kesegaran dan kesejukan alamnya. Ternyata bisa buat Camping ( ada biaya lebih) dan bisa untuk yang suka olah raga sepeda gunung, disediakan track khusus di sini. Biaya tiket masuk @ 5000, biaya parkir 5000(mobil). Anda cukup berjalan sedikit untuk melihat pemandangan bagus puncak Merapi, usahakan pagi hari dan udara cerah.', '2024-02-20 00:00:00', ' Sendiri', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27391, 53, 3936, 'Bukit Klangon adalah salah satu Spot terbaik untuk melihat Gunung Merapi dari dekat serta kota Yogyakarta dari ketinggian, di perkuat dengan hawa khas pegunungan yang sejuk di sertai semilir angin, di dukung cuaca yang cerah dengan langit biru bersih tanpa awan kalimat \"Nikmat mana yang dapat kau dustakan\" sangat cocok untuk menggambarkan suasana itu', '2021-10-13 00:00:00', ' Pasangan', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27392, 53, 2134, 'Pemandangan bagus banget... Terlihat sangat gagah merapinya apalagi kl cuaca lagi cerah... Sayang sekali masih ada perbaikan sarana dan prasarananya', '2022-08-19 00:00:00', ' Sendiri', 4, 1, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27393, 53, 6668, 'Tempat yang sangat indah, untuk memandang puncak gunung merapi yang sangat dekat sambil sesekali mendengar guguran lava yang turun, tempat yang nyaman untuk melepas lelah .... dengan menu minuman panas dan makanan kecil yang harganya sangat terjangkau', '2024-01-25 00:00:00', ' Bisnis', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27394, 53, 1890, 'Pemandangannya bagus banget. Mungkin kesini nya rute yang ditemput lumayan panjang kalo dari kota. Tapi sudah sampe rasanya tu hilang semuanya. Keliatan semua pemandangan seluruh kota', '2022-06-29 00:00:00', ' Teman', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27395, 53, 201, 'Tempat yang cocok menikmati pesona keindahan gunung Merapi sambil ngopi dari dalam tenda.Di samping harganya yang terbilang sangat murah,fasilitas air bersih Dan tempat ibadah juga sudah tersedia.selamat manikmati indahnya puncak Merapi Dr bukit klangon (klangon hill)', '2023-10-02 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27396, 53, 2081, 'Kali pertama diajak lihat gunung merapi yg sudah erupsi dan kebetulan pas cuaca cerah. ternyata pemandangannya luar biasa indah,keren ...disarankan kesini pake jaket/baju hangat ya karna anginnya lumayan kencang dan udaranya lumayan dingin.Disana juga tersedia warung kecil yang menjual makanan hanya sekedar mie goreng/rebus, makanan ringan serta minuman.Jadi jangan takut kelaparan ya', '2024-03-29 00:00:00', ' Sendiri', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27397, 53, 168, 'Tempatnya super duper keren abis, kalau cuaca cerah bisa melihat puncak Merapi dengan sangat jelas. Cocok banget untuk lokasi foto foto dengan background puncak gunung Merapi.', '2020-08-07 00:00:00', ' Bisnis', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27398, 53, 3054, 'Ditempat ini selain untuk berwisatam, dapat juga merasakan sensasi sejuknya menikmati udara daerah pegunungan, serta background berupa gunung Merapi dengan gagahnya.', '2025-02-27 00:00:00', ' Keluarga', 4, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
(27399, 53, 3977, 'Pagi hari udara sejuk, Indah, nikmat gowes bersama 23 asatidz Pondok Pesantren Darunnajah, Klangon ke Prambanan sejauh 23 km', '2021-07-17 00:00:00', ' Keluarga', 5, 0, '2025-10-21 22:21:29', '2025-10-21 22:21:29'),
